base=c2base.base
R=Path(__file__).resolve().parents[2]; C1=R/'reading/french/c1/passages.jsonl'; C2=R/'reading/french/c2/passages.jsonl'; SCHEMA=R/'reading/schema/passage.schema.json'
LOCK=R/'reading/audit/french_c2_unit04_frontier_lock.json'; PLAN=R/'reading/audit/french_c2_unit05_plan.json'; SEL=R/'reading/audit/french_c2_unit05_target_selection.json'
USE={
'spectacle':'Le « spectacle » désigne ici ce qui est organisé pour être perçu : une scène peut transformer un fait banal en événement saillant par le cadrage, l’ordre des détails et l’attente créée chez le lecteur.',
'beauté':'La « beauté » n’est pas traitée comme propriété mesurable isolément, mais comme effet de composition : rythme, contraste, précision et surprise peuvent produire une valeur esthétique sans imposer un jugement identique à tous les lecteurs.',
'étoile':'Une « étoile » peut rester un objet céleste ou devenir signe de distance, de désir ou d’orientation; l’analyse distingue donc le référent littéral de la fonction symbolique que le contexte lui attribue.',
'odeur':'L’« odeur » fournit un détail sensoriel capable d’ouvrir une mémoire, de signaler un lieu ou de contredire une apparence visuelle; son rôle dépend de la relation qu’elle crée avec les autres indices du passage.',
'tableau':'Un « tableau » peut désigner une image construite par la prose : personnages, lumière, gestes et objets sont disposés de façon à produire une impression globale avant même que le récit n’explique leur importance.',
'éloigner':'« Éloigner » peut décrire une distance physique ou narrative. Un narrateur éloigne parfois une émotion en la rapportant froidement, ou rapproche un événement lointain en donnant accès à un détail intime.',
'double':'Le « double » est une structure de ressemblance avec différence : personnage miroir, scène répétée ou formulation parallèle. Il permet de comparer deux possibilités sans les réduire à une copie identique.',
'présence':'La « présence » d’un personnage ne dépend pas seulement du nombre de lignes qui lui sont consacrées; un silence, un objet laissé derrière lui ou la réaction des autres peut le maintenir actif dans la scène.',
'inconnu':'L’« inconnu » peut être une personne, une cause ou une information retenue. En littérature, il organise souvent l’attente en déterminant ce que le lecteur sait, ignore et croit savoir à chaque moment.',
'adieu':'Un « adieu » clôt une relation en apparence, mais sa force rhétorique dépend de ce qui reste non dit : promesse de retour, rupture définitive, ironie ou formule sociale peuvent produire des lectures opposées.',
'discours':'Le « discours » est une prise de parole organisée pour produire un effet sur un destinataire; son analyse porte sur les arguments, mais aussi sur la voix, la sélection des faits et la position attribuée au public.',
'titre':'Le « titre » prépare une lecture avant la première phrase. Il peut annoncer le sujet, créer une énigme, imposer une catégorie ou devenir ironique lorsque le texte dément l’attente qu’il avait installée.',
'nommer':'« Nommer » ne consiste pas seulement à identifier. Choisir entre un nom technique, affectif, péjoratif ou métaphorique cadre déjà l’objet et peut orienter le jugement avant qu’un argument explicite apparaisse.',
'direct':'Un énoncé « direct » réduit parfois la distance entre voix et destinataire, mais simplicité grammaticale et transparence rhétorique ne sont pas synonymes : une formule brève peut cacher une présupposition complexe.',
'justement':'« Justement » peut signaler une précision ou présenter une conclusion comme particulièrement appropriée. Le lecteur vérifie si l’adverbe ajoute une relation démontrée ou s’il donne seulement l’impression que l’enchaînement va de soi.',
'fil':'Le « fil » d’un texte est la continuité qui permet au lecteur de relier scènes, motifs ou arguments. Il peut être chronologique, causal, thématique ou symbolique, et plusieurs fils peuvent se croiser sans devenir équivalents.',
'objet':'Un « objet » littéraire peut être accessoire, indice, symbole ou point de focalisation. Sa fonction se découvre par ses reprises, les actions qu’il déclenche et les contrastes dans lesquels le texte l’insère.',
'inventer':'« Inventer » en littérature ne signifie pas produire arbitrairement. Une fiction construit des contraintes internes, et son invention est évaluée par la cohérence des conséquences, la précision des détails et la fécondité des perspectives ouvertes.',
'fouiller':'« Fouiller » un détail revient à l’examiner au-delà de sa première fonction : choix lexical, position, répétition et écho avec d’autres passages peuvent révéler une organisation que la lecture rapide laisse invisible.',
'taille':'La « taille » d’une phrase, d’une scène ou d’un paragraphe modifie le rythme. L’allongement peut suspendre une conclusion; la brièveté peut accélérer, couper ou donner un poids exceptionnel à une formule.',
'goût':'Le « goût » esthétique combine habitudes, attentes et critères appris. L’analyse peut décrire pourquoi une forme produit un effet sans transformer une préférence personnelle en règle universelle de qualité.',
'presse':'La « presse » représente ici un contexte de circulation : un texte publié pour un lectorat large subit des contraintes de longueur, d’actualité et de lisibilité qui peuvent transformer sa rhétorique.',
'vision':'Une « vision » est à la fois manière de voir et construction interprétative. Un texte peut proposer une vision cohérente tout en signalant les angles morts, intérêts ou limites de la voix qui la porte.',
'saisir':'« Saisir » un passage signifie en reconstruire les relations essentielles, pas seulement reconnaître les mots. Une interprétation forte explique comment les détails soutiennent la lecture et ce qui la rend préférable à une alternative.',
'effacer':'« Effacer » un élément peut être un acte de style : supprimer une explication, un sujet ou une transition oblige le lecteur à combler un lien. L’ellipse produit donc un effet précisément par ce qui manque.'}
EXTRA=[
"Une objection méthodologique rappelle qu’un même procédé peut produire des effets différents selon le contexte. Une répétition peut insister, ironiser, ralentir ou imiter une obsession. L’analyse ne doit donc pas attribuer une fonction à la forme seule; elle relie le procédé à sa position, à ce qui le précède et aux alternatives que le texte aurait pu choisir.",
"Le contreargument le plus utile prend la forme d’une lecture rivale. Au lieu de demander seulement si une interprétation est possible, on cherche quels détails elle explique mieux, lesquels elle laisse sans fonction et quelle autre lecture rendrait le même passage cohérent. La comparaison transforme l’impression de lecture en argument contrôlable.",
"Une ambiguïté peut être volontaire sans devenir illimitée. Le texte peut maintenir deux sens lorsque chacun est soutenu par des indices précis. Si une lecture exige d’ignorer des détails répétés ou d’ajouter des informations absentes, sa plausibilité diminue. L’ouverture interprétative reste ainsi contrainte par la matière du passage.",
"La portée d’un effet doit aussi être située. Une phrase peut changer le ton d’une scène sans définir la voix de l’œuvre entière; un symbole peut fonctionner dans un épisode sans devenir une clé universelle. Le lecteur distingue l’observation locale de la généralisation et cherche des reprises indépendantes avant d’étendre sa conclusion.",
"Enfin, une révision est prévue lorsque le texte résiste à l’hypothèse initiale. Une interprétation n’est pas affaiblie parce qu’elle change; elle devient plus précise lorsqu’elle explique pourquoi certains indices exigeaient une correction. Cette discipline permet de traiter la lecture littéraire comme une construction argumentée plutôt qu’une collection d’associations libres." ]
def h(p):return subprocess.check_output(['git','hash-object',str(p)],text=True).strip()
def fit(ps,lo,hi):
 p=list(ps); t='\n\n'.join(p); i=0
 while len(t.split())<lo and i<len(EXTRA): p[-1]+=' '+EXTRA[i]; i+=1; t='\n\n'.join(p)
 if not lo<=len(t.split())<=hi: raise AssertionError(f'C2 Unit05 word band {len(t.split())} not {lo}-{hi}')
 return p,t
def bridge(fs):return 'Révision interprétative : '+', '.join(f'« {x} »' for x in fs)+'. Ces formes antérieures servent ici à comparer mécanisme, cadrage, transfert et portée dans l’analyse du style.'
def qitems(s,forms):
 core=[('main_claim',s['qclaim'],s['aclaim'],[forms[0]]),('ambiguity_resolution',s['qamb'],s['aamb'],[forms[1]]),('assumption',s['qassume'],s['aassume'],[forms[2]]),('rhetorical_function',s['qrhet'],s['arhet'],[forms[3]]),('stance',s['qstance'],s['astance'],[forms[4]])]
 return core+[('vocabulary_in_context',f'Quel rôle joue « {f} » dans l’analyse ?',USE[f],[f]) for f in forms]
def make(s,forms,reviews,prior,D,lo,hi,theme):
 ps=list(s['paras']); ps[1]+=' '+' '.join(USE[f] for f in forms); ps[2]+=' '+bridge(reviews); ps,text=fit(ps,lo,hi); P=base.prior(prior); new=[c2base.nt(f,text,D) for f in forms]; rev=[base.rev(f,P) for f in reviews]; ids={t['form']:t['id'] for t in new+rev}; q,a=base.qa(qitems(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C2','unit':5,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':['educational','professional'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'integration','description':'integrate syntactic rhythm, modality, ellipsis and interpretive qualification'}],'discourse_targets':[{'id':s['id']+'-d1','role':'integration','description':'reconstruct focalization, rhetorical framing, alternative readings and textual evidence'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C2 Unit05 literary style and rhetoric.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Original fictional literary examples; no copyrighted passage is reproduced.']},'paired_text_group':None,'prerequisites':['French C2 Unit04'],'difficulty_notes_internal':'C2 literary evidence, rhetoric, focalization, ambiguity and revision.','reader_tags':['unit_role:'+s['ptype'],'generation_batch','french_c2_u05']}
def specs(): return [
{'id':'fr-c2-u05-p01','seq':25,'ptype':'instructional','genre':'literary prose','topics':['sensory imagery','symbolic framing'],'title':'La pièce semblait vide jusqu’à ce que le détail prenne la parole','paras':["Dans une prose fictive, une voyageuse entre dans une salle presque vide au coucher du soleil. Le récit ne donne d’abord aucune explication : une pierre claire sur la table, une fenêtre ouverte, une odeur de poussière humide et un reflet isolé sur le mur. La scène paraît descriptive, mais l’ordre des détails prépare progressivement une attente.","L’analyse observe comment le texte transforme la perception en orientation. Le premier détail fixe l’espace, le deuxième introduit un mouvement possible, le troisième évoque une présence antérieure et le dernier attire l’œil vers une zone qui semblait sans importance. Aucun indice ne possède seul une signification complète.","Un contreargument propose de lire ces éléments comme simple décoration. Le passage construit alors une alternative : lorsque la voyageuse revient plus tard, la même pierre a changé de place et l’odeur disparaît après l’ouverture d’une porte cachée. La reprise donne aux détails une fonction narrative sans imposer qu’ils soient tous des symboles. L’effet vient de la relation entre description et conséquence.","Le texte refuse pourtant de résoudre chaque image. Le reflet peut évoquer une étoile sans que le récit déclare ce qu’elle représente. Cette réserve protège une ambiguïté contrôlée : le lecteur peut relier lumière, attente et orientation, mais doit distinguer ce réseau d’indices d’une allégorie totale que rien d’autre ne soutiendrait.","La conclusion présente l’image littéraire comme une opération. Elle sélectionne, ordonne et rend saillant. La beauté éventuelle de la scène n’est donc pas séparée de son travail narratif. Sa portée se mesure à ce que les détails permettent d’anticiper, de ressentir ou de reconsidérer lorsqu’ils réapparaissent."],'qclaim':'Comment la description devient-elle une partie du récit ?','aclaim':'Par la sélection et la reprise de détails sensoriels qui orientent l’attention puis acquièrent une conséquence narrative.','qamb':'Quelle ambiguïté sur le symbole le passage évite-t-il ?','aamb':'Un détail peut produire des associations et des attentes sans devenir automatiquement le symbole total d’une idée unique.','qassume':'Pourquoi le déplacement ultérieur de la pierre est-il important ?','aassume':'Parce qu’il montre que le détail initial n’était pas seulement décoratif et relie la description à une modification de l’action.','qrhet':'Quel rôle joue le refus d’expliquer entièrement le reflet ?','arhet':'Il maintient plusieurs associations possibles tout en laissant les indices textuels limiter les lectures défendables.','qstance':'Quelle conception de la beauté littéraire est proposée ?','astance':'Un effet de composition lié au rythme des détails, à leur relation et à leur fonction plutôt qu’une propriété isolée.'},
{'id':'fr-c2-u05-p02','seq':26,'ptype':'reinforcement','genre':'critical analysis','topics':['narrative distance','doubling','absence'],'title':'Un personnage absent peut occuper toute la scène','paras':["Une nouvelle fictive commence après le départ d’un personnage nommé Léo. Il n’apparaît jamais directement. Pourtant, chaque interlocuteur ajuste sa conduite à ce qu’il croit que Léo aurait dit, une tasse reste posée à sa place et deux scènes reproduisent presque les mêmes gestes avant et après son départ. Le commentaire étudie comment une absence peut construire une forte présence narrative.","La distance est produite par la distribution de l’information. Le lecteur connaît Léo seulement à travers des traces et des voix incompatibles. Une amie le décrit comme prudent, un rival comme imprévisible, et un carnet laissé ouvert contient une phrase qui soutient partiellement les deux portraits.","Le contreargument affirme que cette indétermination empêche toute connaissance du personnage. Une lecture alternative remarque cependant que le désaccord lui-même est informatif : il montre les intérêts des narrateurs secondaires et oblige à séparer ce que Léo a fait de ce que chacun projette sur lui. Le double apparaît lorsque deux scènes parallèles révèlent des réactions opposées au même souvenir.","Le mot d’adieu, rapporté différemment par deux témoins, devient un test de focalisation. L’un l’entend comme rupture; l’autre comme promesse. Le texte n’arbitre pas immédiatement. Cette ambiguïté n’autorise pas n’importe quelle lecture, car certains détails matériels — heure, carnet, geste — restent communs aux récits.","La conclusion distingue absence d’information et organisation de l’absence. Un inconnu complet ne structurerait pas nécessairement la scène; ici, ce qui manque est précisément distribué pour produire comparaison et attente. La portée de l’analyse réside dans cette architecture de traces, non dans une tentative de reconstruire une biographie certaine."],'qclaim':'Comment Léo reste-t-il présent malgré son absence directe ?','aclaim':'Par les traces matérielles, les réactions des autres et les scènes parallèles qui organisent la lecture autour de ce qui manque.','qamb':'Pourquoi les témoignages incompatibles ne rendent-ils pas toute interprétation impossible ?','aamb':'Parce que leurs divergences révèlent les perspectives des témoins tandis que certains faits et objets restent communs.','qassume':'Que suppose l’analyse du double entre les deux scènes ?','aassume':'Que la répétition avec variation est assez précise pour comparer les réactions plutôt que constituer une simple coïncidence.','qrhet':'Pourquoi rapporter deux versions du même adieu ?','arhet':'Pour rendre visible la focalisation : une même formule change de fonction selon l’attente et l’intérêt du témoin.','qstance':'Quelle conception de l’absence défend le passage ?','astance':'L’absence peut être une structure active lorsque le texte distribue les traces et les lacunes de façon organisée.'},
{'id':'fr-c2-u05-p03','seq':27,'ptype':'transfer','genre':'rhetorical commentary','topics':['public speech','framing','presupposition'],'title':'Le mot choisi avant l’argument peut déjà orienter le verdict','paras':["Un discours fictif défend la transformation d’une place publique. Deux versions présentent exactement les mêmes chiffres et le même calendrier. La première parle de « rénovation »; la seconde de « remplacement ». Avant même les arguments, ces verbes installent des attentes différentes sur la continuité, la perte et la légitimité du changement.","L’analyse commence par le titre et les noms. Appeler un bâtiment « héritage », « obstacle » ou « ressource » n’ajoute pas seulement une étiquette : chaque terme sélectionne une propriété et invite le public à traiter certaines conséquences comme centrales. Le cadrage peut donc précéder la preuve explicite.","Un contreargument affirme que le public peut simplement ignorer ces mots et regarder les faits. Une alternative compare alors deux formulations directes qui conservent tous les faits mais changent l’ordre : l’une commence par les bénéfices attendus, l’autre par les pertes certaines. Les réactions peuvent diverger sans qu’aucun chiffre ait été supprimé. Révision interprétative : le choix du cadre fait partie du raisonnement reçu.","L’adverbe « justement » fournit un cas plus discret. Placé avant une conclusion, il peut suggérer que le lien est particulièrement évident. Le lecteur doit vérifier si ce lien a été établi ou si la langue lui prête une nécessité supplémentaire. La même vigilance s’applique aux oppositions présentées comme naturelles plutôt que construites.","La conclusion ne réduit pas toute rhétorique à une manipulation. Nommer et ordonner sont inévitables dès qu’un discours est fini et adressé. L’exigence critique consiste à rendre ces choix visibles, à comparer des formulations rivales et à limiter la portée de l’inférence à ce que les raisons soutiennent réellement."],'qclaim':'Pourquoi le choix des mots importe-t-il même lorsque les faits restent identiques ?','aclaim':'Parce que les noms, titres et ordres de présentation cadrent les propriétés saillantes et les attentes avec lesquelles les faits sont interprétés.','qamb':'Quelle ambiguïté du mot cadrage est évitée ?','aamb':'Le cadrage peut orienter sans falsifier : il sélectionne et ordonne des aspects même lorsque les données présentées restent vraies.','qassume':'Que montre la comparaison de deux ordres de présentation ?','aassume':'Que la réception peut changer lorsque bénéfices et pertes sont hiérarchisés différemment, malgré un contenu factuel identique.','qrhet':'Pourquoi analyser « justement » ?','arhet':'Pour montrer qu’un petit marqueur peut présenter un lien comme acquis et inviter le lecteur à contrôler l’étape argumentative implicite.','qstance':'Quelle position le texte adopte-t-il sur la rhétorique ?','astance':'Elle est inévitable dans toute présentation finie; la critique doit rendre ses choix visibles plutôt que prétendre les supprimer entièrement.'},
{'id':'fr-c2-u05-p04','seq':28,'ptype':'interleaved','genre':'critical analysis','topics':['motif','composition','ellipsis'],'title':'Le fil d’un récit tient parfois à l’objet que personne n’explique','paras':["Un récit fictif suit trois personnages sans narrateur omniscient. Un vieux billet de train passe de main en main, mais personne n’explique pourquoi il compte. Dans la première scène il sert de marque-page; dans la deuxième il tombe d’une poche; dans la troisième quelqu’un le déchire sans commentaire. L’objet forme un fil discret entre des épisodes qui semblaient indépendants.","L’analyse ne cherche pas immédiatement une signification symbolique. Elle commence par la fonction compositionnelle : l’objet crée une continuité, mesure les changements de relation et permet au lecteur de reconnaître une reprise avant que les personnages ne la nomment. Sa petite taille matérielle contraste avec la place qu’il prend dans la mémoire du récit.","Un contreargument propose que le billet ne soit qu’un accessoire réaliste. L’alternative consiste à l’effacer mentalement : si les scènes restent liées avec la même précision, son rôle est faible; si plusieurs transitions et attentes deviennent arbitraires, il participe à l’architecture. Fouiller le texte revient ici à tester les dépendances plutôt qu’à accumuler des associations.","Inventer une explication cachée serait pourtant une erreur symétrique. Le texte ne dit pas que le billet représente le destin, la perte ou le voyage entier. Plusieurs hypothèses restent possibles tant qu’elles rendent compte des mêmes reprises. Une lecture responsable distingue la fonction démontrable — liaison, contraste, déclenchement — du sens thématique encore ouvert.","La conclusion présente la composition comme distribution de contraintes. Un détail peut être petit et structurel. La portée de l’interprétation augmente lorsque plusieurs éléments indépendants convergent : ordre des scènes, gestes, ellipses et retour de l’objet. Elle diminue lorsque le lecteur doit inventer des événements absents pour sauver son hypothèse."],'qclaim':'Pourquoi le billet peut-il être structurel sans recevoir de signification symbolique unique ?','aclaim':'Parce que ses reprises relient les scènes, mesurent les relations et organisent les attentes même si son sens thématique reste ouvert.','qamb':'Quelle ambiguïté entre fonction et symbole est résolue ?','aamb':'Un objet peut avoir une fonction compositionnelle démontrable sans représenter nécessairement une idée unique et cachée.','qassume':'Pourquoi l’effacement mental de l’objet constitue-t-il un test utile ?','aassume':'Parce qu’il permet d’observer quelles relations narratives dépendent réellement de sa présence.','qrhet':'Quel rôle joue l’interdiction d’inventer une explication absente ?','arhet':'Elle limite l’interprétation aux contraintes et reprises du texte plutôt qu’à une histoire ajoutée par le lecteur.','qstance':'Quelle méthode d’analyse est défendue ?','astance':'Tester les dépendances textuelles, comparer des hypothèses et distinguer fonction observable de signification encore indéterminée.'},
{'id':'fr-c2-u05-p05','seq':29,'ptype':'integration','genre':'rhetorical commentary','topics':['reception','editing','media context'],'title':'Changer de public change parfois la forme avant de changer l’idée','paras':["Un même essai fictif existe en trois versions : une conférence longue, un article de presse et une note très courte. La thèse centrale reste stable, mais les transitions, les exemples et la quantité d’incertitude explicitée changent. Le commentaire demande quand ces transformations relèvent de l’adaptation légitime et quand elles finissent par modifier l’argument lui-même.","Le goût du public n’est pas le seul facteur. Chaque support impose une durée, une densité et une relation particulière avec le lecteur. Une conférence peut revenir sur une distinction après une réaction visible; un article doit anticiper l’objection; une note brève choisit ce qu’elle peut laisser implicite.","Un contreargument affirme qu’un bon argument devrait rester identique quel que soit le support. Une alternative distingue structure logique et réalisation discursive. Les raisons principales peuvent rester les mêmes tandis que l’ordre, le rythme et les exemples changent. Révision interprétative : une modification devient substantielle si elle efface une condition nécessaire ou transforme une hypothèse en certitude.","La vision proposée par l’auteur peut donc sembler plus tranchée dans la version courte. Pour saisir l’écart, le lecteur compare ce qui a disparu : réserves, définitions, contre-exemples, limites de portée. L’absence d’un élément n’est pas toujours une faute; elle devient problématique lorsque le lecteur reçoit une conclusion plus forte que les raisons conservées.","La conclusion traite la réception comme partie de la rhétorique. Écrire pour un public suppose des choix, mais ces choix restent évaluables. Une adaptation réussie conserve les relations essentielles, indique honnêtement son degré de certitude et permet encore de distinguer l’argument de la simple impression produite par son style."],'qclaim':'Quand l’adaptation à un support modifie-t-elle réellement l’argument ?','aclaim':'Lorsqu’elle supprime ou transforme une condition, une réserve ou une relation nécessaire au soutien de la conclusion.','qamb':'Quelle distinction entre structure et réalisation est centrale ?','aamb':'Les raisons peuvent rester identiques tandis que rythme, ordre et exemples changent; tout changement de forme n’est donc pas un changement logique.','qassume':'Pourquoi comparer ce qui a été supprimé est-il important ?','aassume':'Parce qu’une version courte peut sembler plus certaine si les limites qui qualifiaient la thèse ont disparu.','qrhet':'Quel rôle joue la comparaison entre trois supports ?','arhet':'Elle sépare les contraintes de réception des éléments nécessaires à l’intégrité de l’argument.','qstance':'Quelle conception de l’adaptation rhétorique est défendue ?','astance':'Elle est légitime si elle respecte les relations essentielles et le degré de certitude, même lorsque la forme change fortement.'}]
def checkpoint(groups,D,lo,hi,theme,prior):
 forms=[f for k in ['p01','p02','p03','p04','p05'] for f in groups[k]]; ps=["Le checkpoint propose un dossier de six fragments originaux : une description sensorielle, un portrait par absence, un discours public, un motif d’objet, deux versions d’un même argument et une courte scène dont la dernière phrase change l’interprétation des précédentes. Le lecteur doit distinguer effet, preuve textuelle et hypothèse de lecture.","La première étape cartographie les procédés sans leur attribuer immédiatement une fonction. Elle relève répétition, contraste, ellipse, changement de distance, ordre des informations et désignation. Révision cumulative : "+'; '.join(f'« {f} »' for f in forms)+". Le lexique devient un outil pour décrire précisément ce que le texte fait avant d’expliquer pourquoi.","La deuxième étape construit au moins une lecture rivale. Pour chaque fragment, le lecteur indique quels détails soutiennent la première interprétation, lesquels soutiennent l’alternative et quel indice permettrait réellement de les départager. Une ambiguïté est conservée lorsqu’aucune lecture n’explique mieux l’ensemble sans coût supplémentaire.","La troisième étape change une forme : supprimer un titre, déplacer une phrase, effacer un objet ou remplacer un mot chargé par un terme plus neutre. Le lecteur prédit l’effet puis compare la version modifiée. Ce contreargument expérimental n’établit pas une intention d’auteur, mais il aide à isoler la fonction d’un procédé.","La conclusion hiérarchise la portée. Une observation locale sur le rythme ne devient pas automatiquement une thèse sur l’œuvre entière; une association personnelle ne devient pas une preuve. Une analyse forte relie forme, position, reprise et conséquence, puis annonce ce qui ferait réviser la lecture." ]; ps,text=fit(ps,lo,hi); P=base.prior(prior); rev=[base.rev(f,P) for f in forms]; ids={t['form']:t['id'] for t in rev}; items=[('main_claim','Quelle discipline générale organise le checkpoint ?','Décrire les procédés, comparer des lectures rivales et relier chaque interprétation à des indices textuels qui en limitent la portée.',[forms[0]]),('ambiguity_resolution','Quand faut-il conserver une ambiguïté ?','Quand plusieurs lectures restent soutenues par les indices sans qu’une alternative explique clairement mieux l’ensemble.',[forms[8]]),('assumption','Pourquoi modifier une forme du texte peut-il être informatif ?','Parce que comparer la version originale et la version modifiée aide à isoler la contribution du procédé à l’effet observé.',[forms[18]]),('rhetorical_function','Pourquoi commencer par nommer les procédés avant d’expliquer leur fonction ?','Pour éviter d’imposer une interprétation avant d’avoir décrit précisément les formes qui doivent la soutenir.',[forms[11]]),('synthesis','Quelle différence sépare impression et argument littéraire ?','L’argument relie l’impression à des détails, des reprises, des alternatives et des limites de portée qui peuvent être discutés.',[forms[20]]),('vocabulary_in_context',f'Quel rôle joue « {forms[3]} » ?',USE[forms[3]],[forms[3]]),('vocabulary_in_context',f'Quel rôle joue « {forms[7]} » ?',USE[forms[7]],[forms[7]]),('vocabulary_in_context',f'Quel rôle joue « {forms[12]} » ?',USE[forms[12]],[forms[12]]),('vocabulary_in_context',f'Quel rôle joue « {forms[16]} » ?',USE[forms[16]],[forms[16]]),('register_style','Pourquoi « justement » mérite-t-il un contrôle argumentatif particulier ?',USE['justement'],['justement'])]; q,a=base.qa(items,ids)
 return {'id':'fr-c2-u05-p06','language':'fr','cefr':'C2','unit':5,'sequence':30,'revision':1,'title':'Checkpoint : justifier une lecture sans fermer le texte','passage_type':'checkpoint','genre':'critical analysis','domains':['educational','professional'],'topics':[theme,'cumulative literary analysis'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':[],'review_lexical_targets':rev,'grammar_targets':[{'id':'fr-c2-u05-p06-g1','role':'integration','description':'integrate interpretive modality, ellipsis and counterfactual comparison'}],'discourse_targets':[{'id':'fr-c2-u05-p06-d1','role':'integration','description':'synthesize imagery, focalization, rhetoric, motif, reception and revision'}],'questions':q,'answer_key':a,'speed_training':{'timed':True,'benchmark_eligible':True,'comprehension_gate':0.8,'new_word_policy':'none','notes':'C2 Unit05 zero-new checkpoint.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Original fictional fragments only.']},'paired_text_group':None,'prerequisites':['French C2 Unit05 P01-P05'],'difficulty_notes_internal':'C2 cumulative literary analysis.','reader_tags':['unit_role:checkpoint','generation_batch','french_c2_u05']}
