 raw=C2.read_text(); rows=[json.loads(x) for x in raw.splitlines() if x.strip()]; l=json.loads(LOCK.read_text()); p=json.loads(PLAN.read_text()); s=json.loads(SEL.read_text()); c1=h(C1); c2=h(C2)
